203	// --- Transcript flush sentinel ---
204	
205	// stopHookSentinel is the string that appears in Claude Code's hook_progress
206	// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
207	const stopHookSentinel = "hooks claude-code stop"
208	
209	// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
210	// Falls back silently after a timeout.
211	func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
212		const (
213			maxWait      = 3 * time.Second
214			pollInterval = 50 * time.Millisecond
215			tailBytes    = 4096
216			maxSkew      = 2 * time.Second
217		)
218	
219		logCtx := logging.WithComponent(ctx, "agent.claudecode")
220	
221		// Fast path: skip the poll loop when the sentinel can't possibly appear.
222		// - File doesn't exist: nothing to poll.
223		// - File is stale (unmodified for 2+ min): agent isn't running anymore.
224		//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
225		//   without firing stop hook).
226		const staleThreshold = 2 * time.Minute
227		info, err := os.Stat(transcriptPath)
228		if err != nil {
229			// Most likely the file doesn't exist; other errors (permission, etc.)
230			// would also prevent polling, so skip the wait either way.
231			return
232		}
233		fileAge := time.Since(info.ModTime())
234		if fileAge > staleThreshold {
235			logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
236				slog.Duration("file_age", fileAge),
237			)
238			return
239		}
240	
241		deadline := time.Now().Add(maxWait)
242		for time.Now().Before(deadline) {
243			if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
244				logging.Debug(logCtx, "transcript flush sentinel found",
245					slog.Duration("wait", time.Since(hookStartTime)),
246				)
247				return
248			}
249			time.Sleep(pollInterval)
250		}
251		logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
252			slog.Duration("timeout", maxWait),
253		)
254	}
255	
256	// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
257	func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
258		f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
259		if err != nil {
260			return false
261		}
262		defer f.Close()
263	
264		info, err := f.Stat()
265		if err != nil {
266			return false
267		}
268		offset := info.Size() - tailBytes
269		if offset < 0 {
270			offset = 0
271		}
272		buf := make([]byte, info.Size()-offset)
273		if _, err := f.ReadAt(buf, offset); err != nil {
274			return false
275		}
276	
277		lines := strings.Split(string(buf), "\n")
278		for _, line := range lines {
279			line = strings.TrimSpace(line)
280			if line == "" || !strings.Contains(line, stopHookSentinel) {
281				continue
282			}
283	
284			var entry struct {
285				Timestamp string `json:"timestamp"`
286			}
287			if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
288				continue
289			}
290			ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
291			if err != nil {
292				ts, err = time.Parse(time.RFC3339, entry.Timestamp)
293				if err != nil {
294					continue
295				}
296			}
297			// Validate timestamp is within acceptable range:
298			// - Not too far in the past (before hook started minus skew)
299			// - Not too far in the future (after hook started plus skew)
300			lowerBound := hookStartTime.Add(-maxSkew)
301			upperBound := hookStartTime.Add(maxSkew)
302			if ts.After(lowerBound) && ts.Before(upperBound) {
303				return true
304			}
305		}
306		return false
307	}
