227	// parseHookType parses a specific hook type from rawHooks into the target slice.
228	// Silently ignores parse errors (leaves target unchanged).
229	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]ClaudeHookMatcher) {
230		if data, ok := rawHooks[hookType]; ok {
231			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
232			json.Unmarshal(data, target)
233		}
234	}
235	
236	// marshalHookType marshals a hook type back to rawHooks.
237	// If the slice is empty, removes the key from rawHooks.
238	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []ClaudeHookMatcher) {
239		if len(matchers) == 0 {
240			delete(rawHooks, hookType)
241			return
242		}
243		data, err := json.Marshal(matchers)
244		if err != nil {
245			return // Silently ignore marshal errors (shouldn't happen)
246		}
247		rawHooks[hookType] = data
248	}
