404	func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
405		for _, matcher := range matchers {
406			for _, hook := range matcher.Hooks {
407				if hook.Command == command {
408					return true
409				}
410			}
411		}
412		return false
413	}
414	
415	func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
416		for _, matcher := range matchers {
417			if matcher.Matcher == matcherName {
418				for _, hook := range matcher.Hooks {
419					if hook.Command == command {
420						return true
421					}
422				}
423			}
424		}
425		return false
426	}
427	
428	func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
429		entry := ClaudeHookEntry{
430			Type:    "command",
431			Command: command,
432		}
433	
434		// If no matcher name, add to a matcher with empty string
435		if matcherName == "" {
436			for i, matcher := range matchers {
437				if matcher.Matcher == "" {
438					matchers[i].Hooks = append(matchers[i].Hooks, entry)
439					return matchers
440				}
441			}
442			return append(matchers, ClaudeHookMatcher{
443				Matcher: "",
444				Hooks:   []ClaudeHookEntry{entry},
445			})
446		}
447	
448		// Find or create matcher with the given name
449		for i, matcher := range matchers {
450			if matcher.Matcher == matcherName {
451				matchers[i].Hooks = append(matchers[i].Hooks, entry)
452				return matchers
453			}
454		}
455	
456		return append(matchers, ClaudeHookMatcher{
457			Matcher: matcherName,
458			Hooks:   []ClaudeHookEntry{entry},
459		})
460	}
