462	// isEntireHook checks if a command is an Entire hook (old or new format)
463	func isEntireHook(command string) bool {
464		for _, prefix := range entireHookPrefixes {
465			if strings.HasPrefix(command, prefix) {
466				return true
467			}
468		}
469		return false
470	}
471	
472	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
473	func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
474		result := make([]ClaudeHookMatcher, 0, len(matchers))
475		for _, matcher := range matchers {
476			filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
477			for _, hook := range matcher.Hooks {
478				if !isEntireHook(hook.Command) {
479					filteredHooks = append(filteredHooks, hook)
480				}
481			}
482			// Only keep the matcher if it has hooks remaining
483			if len(filteredHooks) > 0 {
484				matcher.Hooks = filteredHooks
485				result = append(result, matcher)
486			}
487		}
488		return result
489	}
