74	// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
75	// fires state machine transition.
76	func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
77		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
78		logging.Info(logCtx, "session-start",
79			slog.String("event", event.Type.String()),
80			slog.String("session_id", event.SessionID),
81			slog.String("session_ref", event.SessionRef),
82			slog.String("model", event.Model),
83		)
84	
85		if event.SessionID == "" {
86			return fmt.Errorf("no session_id in %s event", event.Type)
87		}
88		if err := validation.ValidateSessionID(event.SessionID); err != nil {
89			return fmt.Errorf("invalid %s event: %w", event.Type, err)
90		}
91	
92		// Build informational message — warn early if repo has no commits yet,
93		// since checkpoints require at least one commit to work.
94		message := "\n\nPowered by Entire:\n  This conversation will be linked to your next commit."
95		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
96			message = "\n\nPowered by Entire:\n  No commits yet — checkpoints will activate after your first commit."
97		}
98	
99		// Check for concurrent sessions and append count if any
100		_, countSessionsSpan := perf.Start(ctx, "count_active_sessions")
101		strat := GetStrategy(ctx)
102		if count, err := strat.CountOtherActiveSessionsWithCheckpoints(ctx, event.SessionID); err == nil && count > 0 {
103			message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
104		}
105		countSessionsSpan.End()
106	
107		// Output informational message if the agent supports hook responses.
108		// Claude Code reads JSON from stdout; agents that don't implement
109		// HookResponseWriter silently skip (avoids raw JSON in their terminal).
110		_, hookResponseSpan := perf.Start(ctx, "write_hook_response")
111		if event.ResponseMessage != "" {
112			message = event.ResponseMessage
113		}
114		if err := writeSessionStartHookResponse(ctx, ag, message); err != nil {
115			hookResponseSpan.RecordError(err)
116			hookResponseSpan.End()
117			return err
118		}
119		hookResponseSpan.End()
120	
121		// Store model hint if the agent provided model info on SessionStart
122		if event.Model != "" {
123			if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
124				logging.Warn(logCtx, "failed to store model hint on session start",
125					slog.String("error", err.Error()))
